function renderMatches(){const sorted=[...(state.matches||[])].sort((a,b)=>b.startTime-a.startTime),recent=activeRole==="all"?sorted:sorted.filter(m=>m.player?.role===activeRole),history=historyRole==="all"?sorted:sorted.filter(m=>m.player?.role===historyRole);$("#recentMatches").innerHTML=recent.slice(0,5).map(matchCard).join("")||"<p>В этой категории пока нет матчей.</p>";$("#historyMatches").innerHTML=history.map(matchCard).join("")||"<p>В этой категории пока нет матчей.</p>";bindMatchCards();bindPerks()}
function officialCharacters(role,timeframe=characterTimeframe){const key=role==="killer"?"killers":"survivors";return state.officialStats?.timeframes?.[timeframe]?.[key]||[]}
function topCharacterCard(character,index){const rateLabel=character.role==="killer"?"Частота убийств":"Частота побегов";return `<button class="top-character-card" data-character-id="${esc(character.id)}" data-character-role="${character.role}"><span class="top-character-rank">${index+1}</span><div class="top-character-image">${character.image?`<img src="${esc(character.image)}" alt="${esc(character.name)}">`:""}</div><div class="top-character-copy"><h3>${esc(character.name)}</h3><div class="character-stat-line"><span>Часов</span><b>${hoursText(character.hoursPlayed)}</b></div><div class="character-stat-line"><span>Частота выборов</span><b>${percentText(character.pickRate)}</b></div><div class="character-stat-line"><span>${rateLabel}</span><b>${percentText(character.performanceRate)}</b></div></div></button>`}
