function inlineCharacterTable(role,rows){if(characterRole==="all"||rows.length<=3)return"";const rateLabel=role==="killer"?"Частота убийств":"Частота побегов",noun=role==="killer"?"убийцы":"выжившие";return `<section class="inline-character-list"><div class="inline-character-list-title"><div><span class="eyebrow">ОСТАЛЬНЫЕ ПЕРСОНАЖИ</span><h3>Полный рейтинг</h3></div><span>Ещё ${rows.length-3} · места с 4-го</span></div><div class="inline-character-table"><div class="characters-table-head inline-character-table-head"><span>Персонаж</span><span>Часы</span><span>Частота выборов</span><span>${rateLabel}</span></div><div class="inline-character-rows" aria-label="Остальные ${noun}">${rows.slice(3).map((character,index)=>characterTableRow(character,index+3,role,"inline-character-row")).join("")}</div></div></section>`}
function localCharacterFallback(){const grouped={};(state.matches||[]).filter(m=>characterRole==="all"||m.player?.role===characterRole).forEach(m=>{const name=m.player?.character?.name||"Неизвестно",role=m.player?.role||"survivor";grouped[`${role}:${name}`]??={name,role,games:0,kills:0,escapes:0,score:0};const v=grouped[`${role}:${name}`];v.games++;v.kills+=m.kills||0;v.escapes+=escapedResult(m.player?.result)?1:0;v.score+=Number(m.player?.score||0)});const cards=Object.values(grouped).sort((a,b)=>b.games-a.games).map(v=>`<article class="killer-stat-card"><span class="eyebrow">${v.role==="killer"?"УБИЙЦА":"ВЫЖИВШИЙ"}</span><h3>${esc(v.name)}</h3><div><span>Матчей в локальном архиве</span><b>${v.games}</b></div><div><span>${v.role==="killer"?"Убийств":"Побегов"}</span><b>${v.role==="killer"?v.kills:v.escapes}</b></div><div><span>Средние очки</span><b>${Math.round(v.score/v.games).toLocaleString("ru-RU")}</b></div></article>`).join("");return `<div class="official-stats-empty"><b>Расширенная статистика еще не загружена</b><p>Нажмите «Синхронизировать». Companion заберет часы, частоту выборов и полную статистику персонажей из официального DBD Stats Tracker.</p></div><div class="killer-grid">${cards}</div>`}
function renderKillerStats(){const official=state.officialStats,meta=$("#characterStatsMeta"),back=$("#characterOverviewBack");back.hidden=characterRole==="all";if(!official){meta.textContent="Пока показаны данные локальной истории";$("#killerStats").innerHTML=localCharacterFallback();return}const updated=officialDateText(official.updatedAt||official.syncedAt);meta.textContent=`Официальные данные · ${characterTimeframe==="all-time"?"за все время":"за последние 30 дней"}${updated?` · обновлены ${updated}`:""}`;const roles=characterRole==="all"?["killer","survivor"]:[characterRole];$("#killerStats").innerHTML=roles.map(role=>{const rows=officialCharacters(role),title=role==="killer"?"Лучшие убийцы":"Лучшие выжившие",label=role==="killer"?"УБИЙЦЫ":"ВЫЖИВШИЕ",headerAction=characterRole==="all"?`<button data-view-characters="${role}" ${rows.length?"":"disabled"}>Смотреть всех (${rows.length})</button>`:`<span class="character-total-count">Всего персонажей: <b>${rows.length}</b></span>`;return `<section class="character-role-section ${characterRole!=="all"?"is-expanded":""}"><div class="character-role-header"><div><span class="eyebrow">${label}</span><h2>${title}</h2></div>${headerAction}</div>${rows.length?`<div class="top-characters-grid">${rows.slice(0,3).map(topCharacterCard).join("")}</div>${inlineCharacterTable(role,rows)}`:`<div class="official-stats-empty"><b>Нет данных за этот период</b><p>Официальный трекер пока не вернул матчи для этой роли.</p></div>`}</section>`}).join("");$$('[data-view-characters]').forEach(button=>button.onclick=()=>showCharacterRole(button.dataset.viewCharacters));$$('#killerStats [data-character-id]').forEach(button=>button.onclick=()=>openCharacterDetail(button.dataset.characterRole,button.dataset.characterId))}
