function findAddonRow(doc,name){const wanted=cleanWikiText(name).toLocaleLowerCase("ru-RU"),rows=[...doc.querySelectorAll('.mw-parser-output table tr')];return rows.find(row=>{const cells=row.querySelectorAll(':scope > td');if(cells.length<3)return false;const title=cleanWikiText(cells[1].textContent).replace(/\(англ\.[\s\S]*$/i,"").trim().toLocaleLowerCase("ru-RU");return title===wanted||title.startsWith(wanted)})}
