function descriptionFromWiki(html,name,kind){const doc=new DOMParser().parseFromString(html,"text/html");if(/^Аддон/i.test(kind||"")){const addon=addonDetailsFromWiki(doc,name);if(addon)return addon}const item=itemDetailsFromWiki(doc);if(item&&(item.description||item.characteristics.length||item.features.length))return item;const heading=doc.querySelector('#Описание')?.closest('h2'),parts=[];if(heading){for(let node=heading.nextElementSibling;node&&node.tagName!=="H2";node=node.nextElementSibling){const text=cleanWikiText(node.textContent);if(text)parts.push(text)}}const direct=cleanWikiText(doc.querySelector('.perkDesc')?.textContent)||parts.join("\n\n")||[...doc.querySelectorAll('.mw-parser-output > p')].map(node=>cleanWikiText(node.textContent)).filter(text=>text.length>35&&!/^(Эта статья|Навигация|Реклама)/i.test(text)).slice(0,4).join("\n\n");return{description:direct,quote:"",characteristics:[],features:[],featuresLead:""}}
