function renderSettings(){const s=state.settings||{};$("#searchPointLabel").textContent=pointText(s.searchPoint);$("#resultPointLabel").textContent=pointText(s.resultPoint);["perkSlot1","perkSlot2","perkSlot3","perkSlot4","perkSearch","perkResult","perkClear"].forEach(key=>{$(`#${key}PointLabel`).textContent=pointText(s[`${key}Point`])});$("#automationToggle").checked=Boolean(s.automationEnabled);renderWheelSettings()}
function renderUpdateStatus(value={}){const text=$("#updateStatusText"),version=$("#updateVersionText"),button=$("#updateButton"),badge=$("#appVersionBadge");if(badge&&value.currentVersion)badge.textContent=value.currentVersion;if(!text||!version||!button)return;text.textContent=value.message||"Обновления еще не проверялись.";version.textContent=`Текущая версия ${value.currentVersion||"—"}${value.latestVersion&&value.latestVersion!==value.currentVersion?` · последняя ${value.latestVersion}`:""}`;button.disabled=["checking","downloading","installing"].includes(value.status);button.textContent=value.status==="available"?"Скачать и установить":value.status==="downloading"?"Скачивание…":value.status==="installing"?"Перезапуск…":"Проверить обновления";button.dataset.action=value.status==="available"?"install":"check";if(value.notify&&value.status==="available")showToast(value.message,"success")}
