const palette=["#6c1d22","#222329","#8b252b","#303137","#51181c","#28292f"];
function enabledKillers(){const ids=state.settings?.enabledKillerIds||[];return window.FOG_KILLERS.filter(killer=>ids.includes(killer.id))}
function wheelKillers(){const killers=enabledKillers(),cooldown=Math.max(0,Number(state.settings?.wheelCooldown)||0),blocked=new Set((state.randomizer?.killerHistory||[]).slice(-cooldown));if(!cooldown)return killers;const available=killers.filter(killer=>!blocked.has(killer.id));return available.length?available:killers}
function applyWheelRotation(){const canvas=$("#wheelCanvas");canvas.style.transform=`translateZ(0) rotate(${wheelRotation}rad)`}
